// MinimockSignAccessTokenDone returns true if the count of the SignAccessToken invocations corresponds
// the number of defined expectations
func (m *CryptoMock) MinimockSignAccessTokenDone() bool {
	if m.SignAccessTokenMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.SignAccessTokenMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.SignAccessTokenMock.invocationsDone()
}

// MinimockSignAccessTokenInspect logs each unmet expectation
func (m *CryptoMock) MinimockSignAccessTokenInspect() {
	for _, e := range m.SignAccessTokenMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to CryptoMock.SignAccessToken at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterSignAccessTokenCounter := mm_atomic.LoadUint64(&m.afterSignAccessTokenCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.SignAccessTokenMock.defaultExpectation != nil && afterSignAccessTokenCounter < 1 {
		if m.SignAccessTokenMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to CryptoMock.SignAccessToken at\n%s", m.SignAccessTokenMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to CryptoMock.SignAccessToken at\n%s with params: %#v", m.SignAccessTokenMock.defaultExpectation.expectationOrigins.origin, *m.SignAccessTokenMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcSignAccessToken != nil && afterSignAccessTokenCounter < 1 {
		m.t.Errorf("Expected call to CryptoMock.SignAccessToken at\n%s", m.funcSignAccessTokenOrigin)
	}

	if !m.SignAccessTokenMock.invocationsDone() && afterSignAccessTokenCounter > 0 {
		m.t.Errorf("Expected %d calls to CryptoMock.SignAccessToken at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.SignAccessTokenMock.expectedInvocations), m.SignAccessTokenMock.expectedInvocationsOrigin, afterSignAccessTokenCounter)
	}
}

